    public function fetchCampaigns(ConnectedAdAccount $account): array { return ['endpoint'=>'not_requested_delivery_report_only','raw'=>[],'campaigns'=>[]]; }
    public function fetchInsights(ConnectedAdAccount $account,string $startDate,string $endDate): array
    {
        throw new RuntimeException('Apple reports installs, not purchase revenue. Use delivery-report; revenue-table import is intentionally disabled rather than inventing zero sales.');
    }
